import { test, expect } from '@playwright/test';

test.describe('Multi-step form navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/multi-step-form');
    await page.fill(getByLabel('First Name'), 'John');
    await page.fill(getByLabel('Last Name'), 'Doe');
    await page.click(getByRole('button', { name: 'Next' }));
  });

  test('should retain data when going back to the previous step', async ({ page }) => {
    await page.click(getByRole('button', { name: 'Back' }));

    const firstName = await page.inputValue(getByLabel('First Name'));
    const lastName = await page.inputValue(getByLabel('Last Name'));

    expect(firstName).toBe('John');
    expect(lastName).toBe('Doe');
  });

  test('should allow user to proceed after going back', async ({ page }) => {
    await page.click(getByRole('button', { name: 'Back' }));
    await page.fill(getByLabel('First Name'), 'Jane');
    await page.fill(getByLabel('Last Name'), 'Smith');
    await page.click(getByRole('button', { name: 'Next' }));

    const confirmationMessage = await page.getByText('Thank you for your submission!');
    expect(await confirmationMessage.isVisible()).toBeTruthy();
  });
});
